python3 - <<'PY'
import pathlib
p = pathlib.Path('src/ir_lower/expr/array_builtin_args.rs')
t = p.read_text()
old = '''        for variant in variants {
            assert!(
                dispatch.contains(&format!("BuiltinArgumentLowering::{variant} ")),
                "{variant} is declared and selectable but no arm in this file runs it"
            );
        }'''
new = '''        // Comment lines are stripped first: a variant NAMED in prose is exactly the state this
        // test exists to reject, and the arm that ran `ReverseKeySort` was gone while the
        // module still talked about key sorts.
        let code: String = dispatch
            .lines()
            .filter(|line| !line.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\\n");
        for variant in variants {
            assert!(
                code.contains(&format!("BuiltinArgumentLowering::{variant}")),
                "{variant} is declared and selectable but no arm in this file runs it"
            );
        }'''
assert t.count(old) == 1
p.write_text(t.replace(old, new))
print('ok')
